entries[16248] = { ["name"] = "Formula: Enchant Weapon - Unholy", ["text"] = "Use: Teaches you how to perform the Unholy enchantment.\nPermanently enchant a melee weapon to often inflict a curse on the target, inflicting Shadow damage and reducing their melee damage. Cannot be applied to items higher than level 320.\nRequires Classic Enchanting (295)\nSell Price:" }
